static int inotify_fd = -1;
static int tty_fd = -1;
static struct termios orig_termios;
static int termios_saved = 0;
static int termios_raw = 0;

static pid_t awk_pid = -1;
static int awk_wfd = -1; // write end to awk stdin
static char *status_script_path = NULL;

