static int util_argc = 0;

static void set_tty_raw(void) {
    if (tty_fd < 0 || !termios_saved) return;
    if (termios_raw) return;
    struct termios raw = orig_termios;
    raw.c_lflag &= ~(ICANON | ECHO);
    tcsetattr(tty_fd, TCSANOW, &raw);
    termios_raw = 1;
}
static void set_tty_orig(void) {
    if (tty_fd < 0 || !termios_saved) return;
    if (!termios_raw) return;
    tcsetattr(tty_fd, TCSANOW, &orig_termios);
    termios_raw = 0;
}
static void restore_tty(void) {
    if (tty_fd >= 0 && termios_saved && termios_raw) {
        tcsetattr(tty_fd, TCSANOW, &orig_termios);
        termios_raw = 0;
    }
}

static void ensure_pager(void) {
    if (getenv("PAGER") == NULL) {
        setenv("PAGER", "/bin/cat", 1);
    }
}

static void clear_screen(void) {
    if (opt_c_count <= 0) return;
    if (opt_c_count == 1) {
        const char *s = "\033[2J\033[H";
        write(STDOUT_FILENO, s, strlen(s));
    } else {
        const char *s = "\033[2J\033[3J\033[H";
        write(STDOUT_FILENO, s, strlen(s));
    }
}

