    int nraw=0, rawcap=0;
    while (1) {
        ssize_t len = read(inotify_fd, buf, sizeof(buf));
        if (len < 0) {
            if (errno==EAGAIN || errno==EWOULDBLOCK) break;
            if (errno==EINTR) continue;
            break;
        }
        if (len==0) break;
        any=1;
        for (char *p=buf; p<buf+len; ) {
