// -r helpers: kill child group and wait blocking (for restart/exit)
static void r_kill_and_wait(void) {
    if(child_pid<0) return;
    pid_t pid=child_pid;
    int pgid=pid; // child pgid == pid (since setpgid)
    kill(-pgid, restart_sig);
    // Also kill pid directly in case group kill fails? Original likely kills group only. We'll do group.
    int status;
    while(waitpid(pid,&status,0)<0){
        if(errno==EINTR) continue;
        else break;
    }
    child_pid=-1;
}

